        vars['callback_window'] = '; or '.join(lines) if lines else 'none'
        tomorrow = today + datetime.timedelta(days=1)
        vars['callback_facts'] = 'Allowed callback times: ' + vars['callback_window'] + '. Tomorrow is ' + say_date(tomorrow) + ' (' + tomorrow.isoformat() + ').'
    vars['today_iso'] = today.isoformat()
