def embed(obj):
    """A Python expression that rebuilds `obj`, with no brace characters in the source."""
    lit = json.dumps(json.dumps(obj, ensure_ascii=True))
    lit = lit.replace("{", "\\x7b").replace("}", "\\x7d")
    return "json.loads(" + lit + ")"


def pystr(s):
    return embed(s)


def fill(code, data, **subs):
